module Main where
import S_Array
import Control.Exception
import Data.List(intercalate)
trie Null="N"
trie(Leaf n)="L"++show n
trie(a:^:b)="F("++trie a++","++trie b++")"
dump a@(Mk_t_Array(lo,hi) size def root)=
 intercalate "|" [show(lo,hi),show size,show def,trie root,show(s_assocs a),show(sparse_assocs a)]
run :: (Int,Int,[Int],[(Int,Int)],[(Int,Int)]) -> IO ()
run (lo,hi,values,updates,acc)=do
 let a=s_listArray(lo,hi)values
     b=s_def_listArray(lo,hi)0 values
     arrays=[a,b,a //^ updates,b //^ updates,s_accum (-) a acc,s_accum (-) b acc,
       s_amap (*2) b,s_ixmap(lo,hi)(\i->hi-(i-lo))a,
       s_accumArray (+)0(lo,hi)(acc++acc),s_def_array(lo,hi)0[(i,v)|(i,v)<-zip[lo..hi]values]]
 mapM_(putStrLn . dump)arrays
